package owl.nh;
import java.util.*;
import java.nio.file.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
public final class SlayerTests {
 static void check(boolean yes,String why){CoreTests.check(yes,"Slayer: "+why);}
 public static void main(String[] args)throws Exception{
  SlayerCounter c=new SlayerCounter();Object one=new Object(),two=new Object();c.start(10,2);check(!c.died(one,10)&&c.kills==0,"unengaged NPC deaths do not count");c.attack(one,11);check(!c.died(one,11),"other NPC types never count");c.attack(one,10);check(c.died(one,10)&&!c.died(one,10)&&c.kills==1,"one observed attacked NPC death counts once");c.attack(two,10);c.contested(two);check(!c.died(two,10)&&c.kills==1,"contested kills are not credited");c.spawned(two);c.attack(two,10);check(c.died(two,10)&&!c.running&&c.kills==2,"a fresh life can count and the exact goal stops output");c.start(10,1);c.stop();c.attack(one,10);check(!c.died(one,10),"Stop prevents later death callbacks from counting");
  Path temp=Files.createTempDirectory("slayer-launch-");try{Files.createDirectories(temp.resolve("runtime"));Files.writeString(temp.resolve(SlayerLaunchRequest.FILE),"SLAYER_V1");check(SlayerLaunchRequest.consume(temp)&&!SlayerLaunchRequest.consume(temp),"separate app request is consumed once and cleaned");}finally{Files.deleteIfExists(temp.resolve("runtime"));Files.deleteIfExists(temp);}
  taskLoop();manualGoals();superiorSignal();teleportGeometry();automaticGearGate();survival();boost();profiles();lootColours();runtimeSelection();System.out.println("Slayer checks passed: multi-kill continuation, generic superior signal detection, manual-mode isolation, automatic helmet goal, task parsing, panel-relative teleport selection, bounded non-blocking automatic gear preparation, exact NPC type, optional NPC-stat profiles, plugin-colour loot, supplies, combat-flask confirmation, contested deaths, goal stop and passive selection. Synthetic only.");
 }
 static void superiorSignal(){check(SlayerController.superiorAnnouncement("<col=ff0000>A superior foe has appeared...</col>"),"recognize Orion's coloured superior announcement");check(!SlayerController.superiorAnnouncement("[Global] A player says superior foe"),"ignore chat that does not contain Orion's complete superior announcement");java.util.LinkedHashSet<String> names=SlayerController.parseSuperiorNames("  Greater abyssal demon, Marble gargoyle\nNight beast; marble gargoyle ");check(names.size()==3&&names.contains("greater abyssal demon")&&names.contains("marble gargoyle")&&names.contains("night beast"),"parse a case-insensitive, de-duplicated superior list from lines, commas and semicolons");}
 static void manualGoals(){check(SlayerController.selectedGoal(1,57)==57,"one selected kill expands to the visible Slayer-helmet task count");check(SlayerController.selectedGoal(1,0)==1,"one selected kill remains one when no task count is visible");check(SlayerController.selectedGoal(12,57)==12,"values above one remain explicit manual goals");}
 static void teleportGeometry(){java.awt.Rectangle panel=new java.awt.Rectangle(1208,653,764,477),select=SlayerController.teleportSelectTarget(panel),card=SlayerController.teleportResultCardTarget(panel);check(select.contains(1601,837),"visible Select click is anchored to the Teleports panel");check(card.contains(1601,772),"context-menu fallback is anchored to the filtered result card");java.awt.Rectangle moved=new java.awt.Rectangle(208,153,764,477),movedSelect=SlayerController.teleportSelectTarget(moved);check(movedSelect.x==select.x-1000&&movedSelect.y==select.y-500,"moving the client-relative panel moves the target by the same amount");}
 static void automaticGearGate(){
  check(SlayerController.mayAttackAfterGearCheck(false,false,0),"manual mode is not blocked by automatic gear preparation");
  check(SlayerController.mayAttackAfterGearCheck(true,true,0),"observed automatic gear releases Attack immediately");
  for(int delayedTicks=0;delayedTicks<3;delayedTicks++)check(!SlayerController.mayAttackAfterGearCheck(true,false,delayedTicks),"automatic gear receives a bounded two-tick switch and acknowledgement window");
  check(SlayerController.mayAttackAfterGearCheck(true,false,3),"missing Orion item metadata cannot suppress combat indefinitely");
  check(SlayerController.mayAttackAfterGearCheck(true,false,10000),"gear retries remain non-blocking during a long fight");
 }
 private static void taskLoop(){
  SlayerTaskLoop.Task task=SlayerTaskLoop.parse("<col=000000>You're assigned to kill Hellhounds; only 57 more to go.</col>");
  check(task!=null&&task.remaining==57&&task.display.equals("Hellhounds")&&task.target.equals("Hellhound"),"parse a complete assignment and singularize its NPC/search name");
  SlayerTaskLoop.Task current=SlayerTaskLoop.parse("You're still hunting Hellhounds; you have 57 to go. Come back when you've finished your task.");
  check(current!=null&&current.remaining==57&&current.display.equals("Hellhounds")&&current.target.equals("Hellhound"),"parse Nieve's visible existing-task dialogue and use its exact remaining count");
  check(SlayerTaskLoop.parse("[Global] someone: Hellhounds 57")==null,"ignore unrelated player chat");
  check(SlayerTaskLoop.noTask("You don't have a Slayer task; speak to Nieve."),"recognize an explicit no-task game message");
  SlayerTaskLoop loop=new SlayerTaskLoop();loop.start();
  check(loop.running()&&!loop.selectedOnly&&loop.stage==SlayerTaskLoop.Stage.ASSIGNMENT,"Nieve loop starts by requesting an assignment when no current target is supplied");
  loop.stage(SlayerTaskLoop.Stage.WAIT_TELEPORTS,100);check(!loop.stable(true,100,2)&&!loop.stable(true,101,2)&&loop.stable(true,102,2),"interface confirmation requires two complete observed game ticks");check(!loop.stable(false,103,2)&&!loop.stable(true,104,2),"an interrupted interface observation restarts the two-tick confirmation");
  check(loop.observeTarget("Your new assignment is to kill Abyssal demons.")&&loop.acceptObservedCount(57)&&loop.task.target.equals("Abyssal demon")&&loop.task.remaining==57,"combine Nieve's task name with the equipped helmet count without opening an item menu");
  loop.startSelected();loop.acceptKnown("Hellhounds","Hellhound",56,SlayerTaskLoop.Stage.HUNT,10);
  check(loop.running()&&loop.selectedOnly&&loop.task.remaining==56&&loop.stage==SlayerTaskLoop.Stage.HUNT,"selected-NPC mode uses the equipped helmet count directly");
  check(loop.accept("You are assigned to kill Abyssal demons; only 1,234 more to go.")&&loop.task.target.equals("Abyssal demon")&&loop.task.remaining==1234&&loop.stage==SlayerTaskLoop.Stage.GLIDER,"accepted current task captures the full remaining assignment");
  loop.stop();check(!loop.running()&&!loop.selectedOnly&&loop.task==null&&loop.pendingTarget==null,"stop clears task data from memory");
 }
 private static void survival(){
  check(SlayerSurvival.need(79,39,80,40)==SlayerSurvival.Need.HEALTH,"health recovery precedes prayer supplies");
  check(SlayerSurvival.need(80,39,80,40)==SlayerSurvival.Need.PRAYER,"restore below prayer target");
  check(SlayerSurvival.need(80,40,80,40)==SlayerSurvival.Need.NONE,"equal targets do not waste supplies");
  check(SlayerSurvival.need(1,0,0,0)==SlayerSurvival.Need.NONE,"zero disables each target");
  check(SlayerSurvival.restore("Prayer potion(4)")&&SlayerSurvival.restore("Super restore(4)")&&SlayerSurvival.restore("Super restore(1)")&&!SlayerSurvival.restore("Attack potion(4)")&&!SlayerSurvival.restore("Saradomin brew(4)"),"recognize every Super restore dose as a prayer supply without wasting other potions");
  SlayerSurvival s=new SlayerSurvival();s.requested(SlayerSurvival.Need.HEALTH,10,2,50);check(s.waiting(11,2,50),"unconfirmed requests cannot spam next cycle");check(s.waiting(11,1,70),"observed consumption still respects conservative spacing");check(!s.waiting(13,1,70)&&!s.failed(),"confirmed food permits later recovery");
  s.reset();for(int tick=0;tick<9;tick+=3){s.requested(SlayerSurvival.Need.PRAYER,tick,1,10);check(!s.waiting(tick+3,1,10),"unconfirmed request times out");}check(s.failed(),"three ignored supply requests stop retries");s.reset();check(!s.failed()&&!s.waiting(1,0,0),"new run clears pending consumption");
 }
 private static void boost(){
  check(SlayerBoost.needs(108,120,120,108)&&!SlayerBoost.needs(109,109,109,108),"redrink at 108 or below and retain the flask above the threshold");
  SlayerBoost b=new SlayerBoost();b.requested(10,108);check(b.waiting(11,108),"do not spam the reusable flask before confirmation");check(b.waiting(11,120),"an observed stat increase confirms the flask while preserving cooldown");check(!b.waiting(13,120)&&!b.failed(),"confirmed reusable flask permits later actions without requiring an inventory decrement");
 }
 private static void profiles(){
  com.openosrs.client.game.NPCStats mageWeak=com.openosrs.client.game.NPCStats.builder().name("Mage weak").defenceLevel(100).magicLevel(40).slashDef(220).rangeDef(120).magicDef(-20).attackLevel(60).strengthLevel(60).stab(20).slash(20).crush(20).rangeLevel(70).range(30).magic(10).build();
  SlayerNpcProfile.Result first=SlayerNpcProfile.choose(mageWeak);check(first.attackStyle==CombatCore.Style.MAGIC&&first.offensivePrayer==Prayer.AUGURY,"choose magic and Augury against the lowest calculated magic defence");
  com.openosrs.client.game.NPCStats magicThreat=com.openosrs.client.game.NPCStats.builder().name("Magic threat").defenceLevel(100).slashDef(20).rangeDef(80).magicDef(80).attackLevel(50).strengthLevel(50).slash(10).rangeLevel(70).range(20).magicLevel(120).magic(100).bonusMagicDamage(40).build();
  SlayerNpcProfile.Result second=SlayerNpcProfile.choose(magicThreat);check(second.attackStyle==CombatCore.Style.MELEE&&second.offensivePrayer==Prayer.PIETY&&second.protectionPrayer==Prayer.PROTECT_FROM_MAGIC,"separate weakest defence from strongest offensive threat");
  check(SlayerNpcProfile.choose(null)==null,"missing custom NPC stats produce an explicit manual fallback");
 }
 private static void lootColours(){
  java.awt.Color low=new java.awt.Color(0x66B2FF),medium=new java.awt.Color(0x99FF99),high=new java.awt.Color(0xFF9600),insane=new java.awt.Color(0xFF66B2);
  check(SlayerLoot.priceColor(1_000_001,0,net.runelite.client.plugins.grounditems.config.ValueCalculationMode.HIGHEST,20_000,low,100_000,medium,1_000_000,high,10_000_000,insane).equals(high),"the configured strict high-value tier maps to the screenshot orange");
  check(SlayerLoot.priceColor(10_000_001,0,net.runelite.client.plugins.grounditems.config.ValueCalculationMode.HIGHEST,20_000,low,100_000,medium,1_000_000,high,10_000_000,insane).equals(insane),"insane pink loot is not incorrectly treated as orange");
  check(SlayerLoot.priceColor(1_000_000,0,net.runelite.client.plugins.grounditems.config.ValueCalculationMode.HIGHEST,20_000,low,100_000,medium,1_000_000,high,10_000_000,insane).equals(medium),"tier boundaries match the Ground Items plugin's strict greater-than rule");
  java.awt.Color purple=new java.awt.Color(0xAA00FF),filterOrange=new java.awt.Color(0xAF6025),red=new java.awt.Color(0xFF0000);check(SlayerLoot.purpleOrHigher(purple,purple,filterOrange,high,insane,red)&&SlayerLoot.purpleOrHigher(filterOrange,purple,filterOrange,high,insane,red)&&SlayerLoot.purpleOrHigher(red,purple,filterOrange,high,insane,red),"purple plugin highlights and orange/red higher filter tiers are collected");
  check(SlayerLoot.purpleTier(new java.awt.Color(0xB64CFF))&&SlayerLoot.purpleTier(new java.awt.Color(0xFF55B8))&&SlayerLoot.purpleTier(new java.awt.Color(0xE26B24)),"shaded purple, pink and orange loot-filter tiers are collected without exact RGB matches");
  check(!SlayerLoot.purpleTier(new java.awt.Color(0x66CC66))&&!SlayerLoot.purpleTier(new java.awt.Color(0x5599DD))&&!SlayerLoot.purpleTier(java.awt.Color.WHITE),"green, blue and default-white labels do not enter the purple queue");
  check(!SlayerLoot.purpleOrHigher(medium,purple,filterOrange,high,insane,red)&&!SlayerLoot.purpleOrHigher(low,purple,filterOrange,high,insane,red),"lower green and blue tiers remain ignored");
 }
 private static void runtimeSelection()throws Exception{
  Map<String,Object> selfValues=new HashMap<>();selfValues.put("getAnimation",123);selfValues.put("getWorldLocation",new net.runelite.api.coords.WorldPoint(3200,3200,0));Map<String,Object> npcValues=new HashMap<>();npcValues.put("getId",10);npcValues.put("getIndex",7);npcValues.put("getName","Test NPC");NPC npc=fakeNpc(npcValues);selfValues.put("getInteracting",npc);Player self=ChambersTests.fake(Player.class,selfValues);Map<String,Object> values=new HashMap<>();values.put("getLocalPlayer",self);values.put("getGameState",GameState.LOGGED_IN);values.put("getTickCount",10);values.put("getNpcs",Arrays.asList(npc));values.put("getPlayers",Arrays.asList(self));Client client=ChambersTests.fake(Client.class,values);java.lang.reflect.Constructor<net.runelite.client.callback.ClientThread> ctor=net.runelite.client.callback.ClientThread.class.getDeclaredConstructor(Client.class);ctor.setAccessible(true);CombatRuntime r=new CombatRuntime(client,ctor.newInstance(client),new net.runelite.client.eventbus.EventBus(),null);
  r.slayer.replaceSuperiorNamesForSession("Unlisted custom superior");
  try{r.slayer.pick();Map<String,Object> menuValues=new HashMap<>();menuValues.put("getIdentifier",7);menuValues.put("getType",MenuAction.NPC_FIRST_OPTION);MenuOptionClicked click=new MenuOptionClicked(ChambersTests.fake(MenuEntry.class,menuValues));r.slayer.menu(click);check(click.isConsumed()&&!r.slayer.picking&&r.slayer.selected.contains("all matching")&&!r.slayer.running(),"picker selects the NPC kind without starting combat");Map<String,Object> variantValues=new HashMap<>();variantValues.put("getId",11);variantValues.put("getIndex",8);variantValues.put("getName","  test   npc ");NPC variant=fakeNpc(variantValues);Map<String,Object> otherValues=new HashMap<>();otherValues.put("getId",10);otherValues.put("getIndex",9);otherValues.put("getName","Greater Test NPC");NPC other=fakeNpc(otherValues);check(r.slayer.selectedKind(variant),"same named NPC with a different Orion ID belongs to the selected kind");check(!r.slayer.selectedKind(other),"similar but non-identical NPC names remain excluded");r.slayer.start(2);check(r.slayer.running()&&r.slayer.counter.running&&!r.slayer.taskLoop.running()&&r.slayer.counter.goal==2,"manual selected-NPC start remains local and never enters the Home or teleport loop without task evidence");Map<String,Object> superiorValues=new HashMap<>();superiorValues.put("getId",99);superiorValues.put("getIndex",10);superiorValues.put("getName","Unlisted custom superior");superiorValues.put("getWorldLocation",new net.runelite.api.coords.WorldPoint(3201,3200,0));superiorValues.put("getHealthRatio",10);NPC superior=fakeNpc(superiorValues);values.put("getNpcs",Arrays.asList(npc,superior));r.slayer.spawned(superior);r.slayer.chat(ChatMessageType.GAMEMESSAGE,"<col=ff0000>A superior foe has appeared...</col>");r.slayer.died(superior);check(r.slayer.counter.running&&r.slayer.counter.kills==0&&r.slayer.status.contains("Superior defeated"),"a newly spawned listed superior is recognized by exact name, does not consume task progress, and resumes Slayer");values.put("getNpcs",Arrays.asList(npc));r.slayer.counter.stop();r.slayer.counter.start(10,2);r.slayer.animation(self);r.slayer.died(npc);check(r.slayer.running()&&r.slayer.counter.kills==1&&r.slayer.counter.goal==2,"the first production death keeps a multi-kill run active");selfValues.put("getInteracting",variant);r.slayer.animation(self);r.slayer.died(variant);check(r.slayer.counter.kills==2&&r.slayer.settlingLoot(),"a second matching NPC lifetime enters final priority-loot settlement");r.slayer.stop("Synthetic loot settlement complete");r.slayer.lastKilled();check(r.slayer.selected.contains("test")&&r.slayer.selected.contains("all matching"),"manual observed attack followed by death selects every matching NPC");r.slayer.counter.start(10,1);r.slayer.died(npc);check(r.slayer.counter.kills==0,"unobserved deaths do not count in production hook");r.stop("Test F9 equivalent");check(!r.slayer.running()&&!r.slayer.picking,"shared emergency stop cancels Slayer output and picker");}finally{r.slayer.stop("Test cleanup");r.olm.close();}
 }
 private static NPC fakeNpc(Map<String,Object> values){return (NPC)java.lang.reflect.Proxy.newProxyInstance(NPC.class.getClassLoader(),new Class<?>[]{NPC.class},(proxy,method,args)->{if(method.getName().equals("hasAction"))return true;if(method.getName().equals("equals"))return proxy==args[0];if(method.getName().equals("hashCode"))return System.identityHashCode(proxy);Object value=values.get(method.getName());if(value!=null)return value;Class<?> type=method.getReturnType();if(type==boolean.class)return false;if(type==int.class)return -1;if(type==long.class)return 0L;return null;});}
}

